export function topicFor(text){const s=text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/\b(map|report|reporting|host|coordinator|mapa|reporte|reportar|anfitrion|coordinador)\b/.test(s))return 'community';if(/\b(request|status|sent|solicitud|estado|envio|enviada)\b/.test(s))return 'status';if(/\b(medication|medicine|pharmacy|prescription|medicamento|medicamentos|farmacia|receta)\b/.test(s))return 'medication';if(/\b(shelter|transport|transportation|refugio|transporte|bed|alojamiento)\b/.test(s))return 'shelter';if(/\b(alert|alerts|flood|weather|alerta|alertas|inundacion|clima)\b/.test(s))return 'flood';if(/\b(medical|doctor|clinic|medico|medica|clinica)\b/.test(s))return 'medical';return 'start';}
export function emergencyText(text){return /\b(911|drowning|trapped|emergency|emergencia|atrapad[oa]|ahogando|unconscious|inconsciente)\b|can(?:not|'t|’t) breathe|no puedo respirar|chest pain|dolor de pecho/i.test(text);}
